-- Generated by `chainindex dbt` from chains/base.yaml and abis/AerodromePool.json. Do not edit: change the chain file or ABI and regenerate.
-- Swap(address,address,uint256,uint256,uint256,uint256)
{{ config(
    materialized='view',
    schema='events_base',
    alias='aerodrome_pool__swap',
    tags=['chains', 'chain_base'],
) }}

select
    toUInt64(8453) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    concat('0x', substring(substring(topic1, 3, 64), 25, 40)) as sender,
    concat('0x', substring(substring(topic2, 3, 64), 25, 40)) as to,
    reinterpretAsUInt256(reverse(unhex(substring(data, 3, 64)))) as amount0_in,
    reinterpretAsUInt256(reverse(unhex(substring(data, 67, 64)))) as amount1_in,
    reinterpretAsUInt256(reverse(unhex(substring(data, 131, 64)))) as amount0_out,
    reinterpretAsUInt256(reverse(unhex(substring(data, 195, 64)))) as amount1_out
from {{ source('chain_base', 'logs') }}
where topic0 = '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b'
  and address in (select address from {{ ref('base__contracts') }} where contract = 'aerodrome_pool')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_base', 'orphaned_blocks') }}
  )
